import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { EventosService, Evento } from '../../../../services/eventos.service';

@Component({
  selector: 'app-editar-evento',
  templateUrl: './editar-evento.component.html',
  styleUrls: ['./editar-evento.component.css']
})
export class EditarEventoComponent implements OnInit {
  form: FormGroup;
  cargando: boolean = false;
  cargandoInicial: boolean = true;
  error: string = '';
  eventoId: string = '';

  constructor(
    private fb: FormBuilder,
    private eventosService: EventosService,
    private route: ActivatedRoute,
    private router: Router
  ) {
    this.form = this.fb.group({
      titulo: ['', [Validators.required, Validators.minLength(3)]],
      fecha: ['', Validators.required],
      ubicacion: ['', Validators.required],
      probabilidadInasistencia: [0, [Validators.min(0), Validators.max(100)]],
      comunidad: [''],
      estado: ['programado']
    });
  }

  ngOnInit(): void {
    this.eventoId = this.route.snapshot.paramMap.get('id') || '';
    if (!this.eventoId) {
      this.error = 'ID de evento no válido';
      this.cargandoInicial = false;
      return;
    }
    this.cargarEvento();
  }

  cargarEvento(): void {
    // Como el backend no tiene GET /:id, traemos todos y filtramos
    this.eventosService.obtenerEventos().subscribe({
      next: (eventos) => {
        const evento = eventos.find(e => e._id === this.eventoId);
        if (!evento) {
          this.error = 'Evento no encontrado';
          this.cargandoInicial = false;
          return;
        }
        this.precargarFormulario(evento);
        this.cargandoInicial = false;
      },
      error: (err) => {
        console.error(err);
        this.error = 'Error al cargar el evento';
        this.cargandoInicial = false;
      }
    });
  }

  private precargarFormulario(evento: Evento): void {
    // Convertir fecha a formato datetime-local (YYYY-MM-DDTHH:mm)
    const fechaInput = evento.fecha
      ? new Date(evento.fecha).toISOString().slice(0, 16)
      : '';

    const comunidadVal = typeof evento.comunidad === 'string' ? evento.comunidad : '';

    this.form.patchValue({
      titulo: evento.titulo,
      fecha: fechaInput,
      ubicacion: evento.ubicacion,
      probabilidadInasistencia: evento.probabilidadInasistencia ?? 0,
      comunidad: comunidadVal,
      estado: evento.estado ?? 'programado'
    });
  }

  guardar(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    this.cargando = true;
    this.error = '';

    const datos: any = { ...this.form.value };
    if (!datos.comunidad) delete datos.comunidad;

    this.eventosService.actualizarEvento(this.eventoId, datos).subscribe({
      next: () => {
        this.cargando = false;
        this.router.navigate(['/eventos']);
      },
      error: (err) => {
        console.error(err);
        this.error = err?.error?.msg || 'Error al actualizar el evento';
        this.cargando = false;
      }
    });
  }

  cancelar(): void {
    this.router.navigate(['/eventos']);
  }

  campoInvalido(campo: string): boolean {
    const c = this.form.get(campo);
    return !!c && c.invalid && (c.dirty || c.touched);
  }
}
<div class="form-container">
  <header class="form-header">
    <h1>Editar evento</h1>
    <p class="subtitle">Modifica los datos del evento</p>
  </header>

  <app-loader *ngIf="cargandoInicial" message="Cargando evento..."></app-loader>

  <div *ngIf="error && !cargandoInicial" class="alert alert-error">{{ error }}</div>

  <form *ngIf="!cargandoInicial" [formGroup]="form" (ngSubmit)="guardar()" class="evento-form">
    <div class="form-group">
      <label for="titulo">Título <span class="required">*</span></label>
      <input id="titulo" type="text" formControlName="titulo" />
      <small *ngIf="campoInvalido('titulo')" class="error-text">
        El título es obligatorio (mínimo 3 caracteres)
      </small>
    </div>

    <div class="form-row">
      <div class="form-group">
        <label for="fecha">Fecha y hora <span class="required">*</span></label>
        <input id="fecha" type="datetime-local" formControlName="fecha" />
        <small *ngIf="campoInvalido('fecha')" class="error-text">La fecha es obligatoria</small>
      </div>

      <div class="form-group">
        <label for="ubicacion">Ubicación <span class="required">*</span></label>
        <input id="ubicacion" type="text" formControlName="ubicacion" />
        <small *ngIf="campoInvalido('ubicacion')" class="error-text">La ubicación es obligatoria</small>
      </div>
    </div>

    <div class="form-row">
      <div class="form-group">
        <label for="probabilidad">Probabilidad de inasistencia (%)</label>
        <input id="probabilidad" type="number" formControlName="probabilidadInasistencia" min="0" max="100" />
        <small *ngIf="campoInvalido('probabilidadInasistencia')" class="error-text">
          Debe ser entre 0 y 100
        </small>
      </div>

      <div class="form-group">
        <label for="estado">Estado</label>
        <select id="estado" formControlName="estado">
          <option value="programado">Programado</option>
          <option value="en curso">En curso</option>
          <option value="finalizado">Finalizado</option>
          <option value="cancelado">Cancelado</option>
        </select>
      </div>
    </div>

    <div class="form-group">
      <label for="comunidad">Comunidad</label>
      <input id="comunidad" type="text" formControlName="comunidad" />
    </div>

    <div class="form-actions">
      <app-button label="Cancelar" variant="secondary" (clicked)="cancelar()"></app-button>
      <app-button label="Guardar cambios" type="submit" [disabled]="form.invalid" [loading]="cargando"></app-button>
    </div>
  </form>
</div>
